package br.com.marealta.pousada.domain;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.Month;

public final class Pricing {
    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");

    private Pricing() {
    }

    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    public static boolean highSeason(LocalDate night) {
        Month month = night.getMonth();
        return month == Month.JULY
                || month == Month.JANUARY
                || month == Month.FEBRUARY
                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    }

    public static BigDecimal nightPrice(Room room, LocalDate night) {
        BigDecimal rate = room.nightlyRate();
        return Money.round(highSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    }

    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
        BigDecimal subtotal = Money.ZERO;
        int nights = 0;
        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
            nights++;
        }
        BigDecimal discount = plan.discountOn(subtotal);
        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    }
}
EOF
cat > domain/Reservation.java <<'EOF'
package br.com.marealta.pousada.domain;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;

public record Reservation(
        long id,
        int roomNumber,
        String guestName,
        String guestEmail,
        String guestCpf,
        LocalDate checkIn,
        LocalDate checkOut,
        int guests,
        RatePlan ratePlan,
        int nights,
        BigDecimal subtotal,
        BigDecimal discount,
        BigDecimal total,
        Status status,
        BigDecimal amountPaid,
        BigDecimal refund) {

    public Reservation confirm() {
        requireStatus("confirmada", Status.PENDING);
        return with(Status.CONFIRMED, total, refund);
    }

    public Reservation checkIn() {
        requireStatus("feito o check-in", Status.CONFIRMED);
        return with(Status.CHECKED_IN, amountPaid, refund);
    }

    public Reservation checkOut() {
        requireStatus("feito o check-out", Status.CHECKED_IN);
        return with(Status.CHECKED_OUT, amountPaid, refund);
    }

    public Reservation cancel() {
        requireStatus("cancelada", Status.PENDING, Status.CONFIRMED);
        return with(Status.CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
    }

    /** O que ficou com a pousada: pago menos devolvido. */
    public BigDecimal retained() {
        return Money.round(amountPaid.subtract(refund == null ? Money.ZERO : refund));
    }

    public boolean occupies(LocalDate night) {
        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    }

    private void requireStatus(String action, Status... allowed) {
        if (!Arrays.asList(allowed).contains(status)) {
            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,
                    "A reserva " + id + " está " + status + " e não pode ser " + action);
        }
    }

    private Reservation with(Status newStatus, BigDecimal newAmountPaid, BigDecimal newRefund) {
        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
                ratePlan, nights, subtotal, discount, total, newStatus, newAmountPaid, newRefund);
    }
}
